#define MOHMD_NR(RET, NAME, ARGS) \
    RET(*o##NAME)               \
    ARGS;                       \
    RET h##NAME ARGS            \
    {                           \
    asm volatile( \
    "mov r0, #0\n"  \
    ); \
}

#define MOHMD(RET, NAME, ARGS) \
  RET(*o##NAME) ARGS; \
  RET h##NAME ARGS
