bool isAPKRunning(const char* packageNamepepe) {
    DIR* dir = opendir("/proc/");
    if (!dir) return false;
    struct dirent* ptr;
    char filepath[50], filetext[128];
    while ((ptr = readdir(dir)) != nullptr) {
        if (ptr->d_type != DT_DIR) continue;
        snprintf(filepath, sizeof(filepath), "/proc/%s/cmdline", ptr->d_name);
        FILE* fp = fopen(filepath, "r");
        if (fp) {
            if (fgets(filetext, sizeof(filetext), fp)) {
                fclose(fp);
                if (strcmp(filetext, packageNamepepe) == 0) {
                    closedir(dir);
                    return true;
                }
            } else {
                fclose(fp);
            }
        }
    }
    closedir(dir);
    return false;
}

const char* GetPackageNamepepe() {
    if (isAPKRunning(PKG_GL)) return PKG_GL;
    if (isAPKRunning(PKG_VNG)) return PKG_VNG;
    if (isAPKRunning(PKG_KR)) return PKG_KR;
    if (isAPKRunning(PKG_TW)) return PKG_TW;
    if (isAPKRunning(PKG_IN)) return PKG_IN;
    return "unknown pkg";
}

bool checkFileForPlugin() {
    std::ifstream file("/proc/self/cmdline");
    std::string line;
    if (file.is_open()) {
        if (std::getline(file, line)) {
            file.close();
            if (line.find(":plugin") != std::string::npos) {
                kill(getpid(), SIGSTOP);
                pthread_exit(NULL);
                return true;
            }
        }
        file.close();
    }
    return false;
}
