// ============================ Helper Functions ============================
std::string demangle(const char* symbol) {
    size_t size;
    int status;
    char* demangled = abi::__cxa_demangle(symbol, nullptr, &size, &status);
    std::string result = (status == 0) ? demangled : symbol;
    free(demangled);
    return result;
}

static std::pair<std::string, uintptr_t> GetRVA(unsigned long addr) {
	Dl_info dl;
	if (dladdr(reinterpret_cast<void*>(addr), &dl) == 0) return { std::string(), 0 };
	const char* fname = dl.dli_fname ? dl.dli_fname : "";
	std::string full(fname);
	std::string libname = full.substr(full.find_last_of('/') + 1);
	void* base = dl.dli_fbase ? dl.dli_fbase : nullptr;
	uintptr_t rva = base ? (uintptr_t)reinterpret_cast<void*>(addr) - (uintptr_t)base : 0;
	return { libname, rva };
}
