std::vector<std::string> Logs;
std::mutex LogMutex;

const char* LogFilePath = "/storage/emulated/0/Android/data/com.pubg.krmobile/files/log.txt";
void AddLog(const char* fmt, ...) {
char buffer[512];
va_list args;
va_start(args, fmt);
vsnprintf(buffer, sizeof(buffer), fmt, args);
va_end(args);
std::lock_guard<std::mutex> lock(LogMutex);
Logs.push_back(buffer);
if (Logs.size() > 500)
Logs.erase(Logs.begin());
std::ofstream logFile(LogFilePath, std::ios::app);
if (logFile.is_open()) {
logFile << buffer << std::endl;
logFile.close();
}}
bool RoundToggleButton(const char* label, bool* v) {
ImVec2 p = ImGui::GetCursorScreenPos();
ImDrawList* draw_list = ImGui::GetWindowDrawList();
float height = 24.0f;
float width = height * 2.0f;
float radius = height * 0.5f;

ImGui::InvisibleButton(label, ImVec2(width, height));
if (ImGui::IsItemClicked())
*v = !*v;

ImU32 col_bg;
if (*v)
col_bg = ImColor(0, 255, 0, 255);
else
col_bg = ImColor(40, 40, 50, 255);

draw_list->AddRectFilled(p, ImVec2(p.x + width, p.y + height), col_bg, height * 0.5f);
draw_list->AddCircleFilled(ImVec2(p.x + (*v ? (width - radius) : radius), p.y + radius),
 radius - 4.0f, ImColor(255, 255, 255, 255));

ImGui::SameLine();
ImGui::TextUnformatted(label);

return *v;
}

struct BacktraceState {
    void** current;
    void** end;
};

_Unwind_Reason_Code unwindCallback(struct _Unwind_Context* context, void* arg) {
    BacktraceState* state = static_cast<BacktraceState*>(arg);
    uintptr_t pc = _Unwind_GetIP(context);
    if (pc == 0) {
        return _URC_END_OF_STACK;
    }
    if (state->current < state->end) {
        *state->current++ = reinterpret_cast<void*>(pc);
    }
    return _URC_NO_REASON;
}

std::vector<void*> captureBacktrace(size_t maxFrames = 32) {
    std::vector<void*> stack(maxFrames, nullptr);
    BacktraceState state = { stack.data(), stack.data() + maxFrames };
    _Unwind_Backtrace(unwindCallback, &state);
    stack.resize(state.current - stack.data());
    return stack;
}

uintptr_t getLibraryBase2(const std::string& libName) {
    std::ifstream maps(oxorany("/proc/self/maps"));
    if (!maps.is_open()) {
        return 0;
    }
    std::string line;
    while (std::getline(maps, line)) {
        if (line.find(libName) != std::string::npos) {
            uintptr_t base;
            if (sscanf(line.c_str(), oxorany("%lx-"), &base) == 1) {
                return base;
            }
        }
    }
    return 0;
}

static std::string getLibraryName2(void* address, uintptr_t& offset) {
    std::vector<std::string> libraries = {
        "libUE4.so", "libc.so", "libmeemo_mmkv.so", "libTDataMaster.so", "libgcloud.so",
        "libanogs.so", "libanort.so", "libCrashSight.so", "libapp.so", "libav1d.so",
        "libav1d_jni.so", "libavif_android.so", "libc++_shared.so", "libcubehawk.so",
        "libflutter.so", "libgamemaster.so", "libgcloudarch.so", "libgcloudcore.so",
        "libGCloudVoice.so", "libgnustl_shared.so", "libGvoiceNN.so", "libijkffmpeg.so",
        "libINTLCompliance.so", "libINTLFoundation.so", "libITOP.so", "libkk-image.so",
        "libmarsxlog.so", "libmmkv.so", "libnpps-jni.so", "libopenplatform.so",
        "libPandoraVideo.so", "libPixUI_PXPlugin.so", "libpixuiCurl.so", "libPxExtFFi.so",
        "libsentry.so", "libsentry-android.so", "libspecialgem.so", "libswappy.so",
        "libtgpa.so", "libtool-checker.so", "libvlink.so"
    };

    Dl_info info;
    if (dladdr(address, &info) && info.dli_fname) {
        std::string fullPath = info.dli_fname;
        size_t pos = fullPath.find_last_of("/");
        std::string libName = (pos != std::string::npos) ? fullPath.substr(pos + 1) : fullPath;

        uintptr_t libBase = getLibraryBase2(libName);
        if (libBase != 0) {
            offset = reinterpret_cast<uintptr_t>(address) - libBase;
        } else {
            offset = reinterpret_cast<uintptr_t>(address);
        }

        for (const auto& lib : libraries) {
            if (libName.find(lib) != std::string::npos) {
                return lib;
            }
        }
        return libName;
    }

    offset = reinterpret_cast<uintptr_t>(address);
    return "UnknownLibrary";
}

void BT(char* format, ...) {
    if (!EnableLog || !format) return;
    char dest[4096];
    va_list argptr;
    va_start(argptr, format);
    vsnprintf(dest, sizeof(dest), format, argptr);
    va_end(argptr);

    std::vector<void*> backtrace = captureBacktrace();
    if (backtrace.empty()) {
        return;
    }

    std::ostringstream traceLog;
    traceLog << dest;

    bool firstEntry = true;
    for (size_t i = 1; i < backtrace.size(); ++i) { 
        if (backtrace[i] == nullptr) {
            continue;
        }

        uintptr_t offset = 0;
        std::string libName = getLibraryName2(backtrace[i], offset);


        if (libName == oxorany("libCrashSightPlugin.so") || libName == oxorany("libAkAudioVisiual.so") || libName == oxorany("libc.so")) {
            continue;
        }
        if (!firstEntry) {
            traceLog << oxorany(" <-- ");
        }
        traceLog << libName << oxorany(" + 0x") << std::hex << offset;
        firstEntry = false;
    }

    if (firstEntry) {
        return;
    }

    AddLog(oxorany("%s"), traceLog.str().c_str());
    AddLog(oxorany("-----------------------------------------"));
}
