static std::unordered_set<uint32_t> loggedHashes;
inline uint32_t djb2_hash(const char* str) {
    uint32_t hash = 5381;
    while (*str)
        hash = ((hash << 5) + hash) + static_cast<uint8_t>(*str++);
    return hash;
}

#define LOGU(format, ...) do { \
    char buffer[1024]; \
    snprintf(buffer, sizeof(buffer), format, ##__VA_ARGS__); \
    uint32_t hash = djb2_hash(buffer); \
    if (loggedHashes.insert(hash).second) { \
        __android_log_print(ANDROID_LOG_INFO, TAG, "%s", buffer); \
    } \
} while (0)
